# GKE Cluster definition
resource "google_container_cluster" "primary" {
  name     = "prod-gke-cluster"
  location = "us-central1" # Regional cluster for high availability

  # Immediately delete default node pool to replace it with a separately managed pool
  remove_default_node_pool = true
  initial_node_count       = 1

  network    = google_compute_network.gke_vpc.self_link
  subnetwork = google_compute_subnetwork.gke_subnet.self_link

  ip_allocation_policy {
    cluster_secondary_range_name  = "gke-pods"
    services_secondary_range_name = "gke-services"
  }

  # Private cluster configuration - nodes have no public IP addresses
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }

  # Enable Workload Identity for pod-to-GCP-API access without static keys
  workload_identity_config {
    workload_pool = "${data.google_project.current.project_id}.svc.id.goog"
  }

  release_channel {
    channel = "REGULAR"
  }

  # Set deletion protection for production clusters
  deletion_protection = false
}

