# Terraform configuration for a MySQL Cloud SQL instance with Public IP and Authorized Networks

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to deploy the Cloud SQL instance in."
}

variable "region" {
  type        = string
  description = "The GCP region to host the Cloud SQL instance."
  default     = "us-central1"
}

variable "office_vpn_cidr" {
  type        = string
  description = "The CIDR block of the office VPN allowed to access the Cloud SQL instance."
  default     = "203.0.113.0/24" # Replace with actual office VPN external IP/range
}

variable "database_version" {
  type        = string
  description = "The MySQL database engine version."
  default     = "MYSQL_8_0"
}

variable "tier" {
  type        = string
  description = "The machine tier for the Cloud SQL instance."
  default     = "db-custom-2-7680"
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Generate a random suffix for unique resource naming
resource "random_id" "db_suffix" {
  byte_length = 4
}

# Random password for the MySQL administrative user
resource "random_password" "root_password" {
  length  = 24
  special = true
}

# MySQL Cloud SQL Instance with Public IPv4 and Authorized Network configuration
resource "google_sql_database_instance" "mysql_public" {
  name                = "mysql-instance-${random_id.db_suffix.hex}"
  database_version    = var.database_version
  region              = var.region
  deletion_protection = false # Set to true for production workloads

  settings {
    tier = var.tier

    ip_configuration {
      # Enable public IPv4 address assignment
      ipv4_enabled = true

      # Restrict public access exclusively to the specified office VPN CIDR
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }

    disk_autoresize = true
    disk_size       = 20
    disk_type       = "PD_SSD"
  }
}

# Primary application database
resource "google_sql_database" "app_db" {
  name     = "app_db"
  instance = google_sql_database_instance.mysql_public.name
  charset  = "utf8mb4"
  collation = "utf8mb4_unicode_ci"
}

# Root/Admin user with access permitted from the authorized office VPN
resource "google_sql_user" "admin_user" {
  name     = "app_admin"
  instance = google_sql_database_instance.mysql_public.name
  password = random_password.root_password.result
  host     = "%"
}

# Outputs
output "instance_name" {
  description = "The name of the database instance."
  value       = google_sql_database_instance.mysql_public.name
}

output "public_ip_address" {
  description = "The assigned public IPv4 address of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_public.public_ip_address
}

output "database_user" {
  description = "The administrator database username."
  value       = google_sql_user.admin_user.name
}

output "database_password" {
  description = "The generated administrator password."
  value       = random_password.root_password.result
  sensitive   = true
}

