# Input variables
variable "project_id" {
  description = "The GCP project ID to deploy resources into"
  type        = string
}

variable "region" {
  description = "The GCP region for regional resources"
  type        = string
  default     = "us-central1"
}

variable "bucket_name" {
  description = "Globally unique name for the Cloud Storage bucket"
  type        = string
}

variable "location" {
  description = "Location for the Cloud Storage bucket (e.g., US, EU, us-central1)"
  type        = string
  default     = "US"
}

# Cloud Storage Bucket configured for static website hosting
resource "google_storage_bucket" "static_website" {
  name          = var.bucket_name
  location      = var.location
  force_destroy = true

  # Enable uniform bucket-level access for consistent IAM controls
  uniform_bucket_level_access = true

  website {
    main_page_suffix = "index.html"
    not_found_page   = "404.html"
  }

  cors {
    origin          = ["*"]
    method          = ["GET", "HEAD", "OPTIONS"]
    response_header = ["*"]
    max_age_seconds = 3600
  }
}

