output "bucket_name" {
  description = "Name of the created GCS bucket"
  value       = google_storage_bucket.static_website.name
}

output "bucket_url" {
  description = "Base GCS URL for the bucket"
  value       = google_storage_bucket.static_website.url
}

output "website_url" {
  description = "Public web endpoint for the static website"
  value       = "https://storage.googleapis.com/${google_storage_bucket.static_website.name}/${google_storage_bucket.static_website.website[0].main_page_suffix}"
