# Firewall rule allowing inbound TCP port 22 strictly from 203.0.113.0/24
resource "google_compute_firewall" "allow_ssh_trusted" {
  name        = "allow-ssh-restricted"
  network     = google_compute_network.default.name
  description = "Allows inbound TCP port 22 (SSH) only from 203.0.113.0/24"
  direction   = "INGRESS"
  priority    = 1000

  allow {
    protocol = "tcp"
    ports    = ["22"]
  }

  source_ranges = ["203.0.113.0/24"]

  # Enable logging for security monitoring and audit trail
  log_config {
    metadata = "INCLUDE_ALL_METADATA"
  }
}

