  account_id   = "vm-dedicated-sa"
  display_name = "Dedicated VM Service Account"
  description  = "Dedicated service account running the private Compute Engine instance"
}

# Custom VPC Network
resource "google_compute_network" "vpc_network" {
  name                    = "private-vpc"
  auto_create_subnetworks = false
}

# Private Subnet with Private Google Access enabled
resource "google_compute_subnetwork" "private_subnet" {
  name                     = "private-subnet"
  ip_cidr_range            = "10.10.1.0/24"
  region                   = "us-central1"
  network                  = google_compute_network.vpc_network.id
  private_ip_google_access = true
}

# Compute Engine Instance without an External IP
resource "google_compute_instance" "private_vm" {
  name         = "private-compute-instance"
  machine_type = "e2-medium"
  zone         = "us-central1-a"

  boot_disk {
    initialize_params {
      image = "debian-cloud/debian-12"
      size  = 20
      type  = "pd-standard"
    }
  }

  # Network interface with no access_config block ensures no external public IP is allocated
  network_interface {
    network    = google_compute_network.vpc_network.id
    subnetwork = google_compute_subnetwork.private_subnet.id
  }

  # Running as the dedicated service account with the standard cloud-platform scope
  service_account {
    email  = google_service_account.vm_service_account.email
    scopes = ["cloud-platform"]
  }

  shielded_instance_config {
    enable_secure_boot          = true
    enable_vtpm                 = true
    enable_integrity_monitoring = true
  }
}

