# Fetch the current project details for project number
data "google_project" "project" {}

# Main topic to which messages are published
resource "google_pubsub_topic" "main" {
  name = "main-topic"
}

# Dead-letter topic where unacknowledged messages are forwarded after delivery limits are exceeded
resource "google_pubsub_topic" "dead_letter" {
  name = "dead-letter-topic"
}

# Cloud Pub/Sub service account must have publisher permissions on the dead-letter topic
resource "google_pubsub_topic_iam_member" "dead_letter_publisher" {
  topic  = google_pubsub_topic.dead_letter.id
  role   = "roles/pubsub.publisher"
  member = "serviceAccount:service-${data.google_project.project.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

# Subscription with dead-letter policy configured to give up after 5 delivery attempts
resource "google_pubsub_subscription" "main" {
  name  = "main-subscription"
  topic = google_pubsub_topic.main.id

  dead_letter_policy {
    dead_letter_topic     = google_pubsub_topic.dead_letter.id
    max_delivery_attempts = 5
  }

  # Ensure the service account has permission to publish to the dead-letter topic prior to subscription creation
  depends_on = [
    google_pubsub_topic_iam_member.dead_letter_publisher
  ]
}

# Cloud Pub/Sub service account must also have subscriber permissions on the main subscription
resource "google_pubsub_subscription_iam_member" "main_subscriber" {
  subscription = google_pubsub_subscription.main.id
  role         = "roles/pubsub.subscriber"
  member       = "serviceAccount:service-${data.google_project.project.number}@gcp-sa-pubsub.iam.gserviceaccount.com"
}

