# Terraform configuration for a MySQL Cloud SQL instance with public IP enabled
# and restricted via authorized networks for office VPN access.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

variable "project_id" {
  type        = string
  description = "The GCP Project ID to host the database."
}

variable "region" {
  type        = string
  description = "The GCP region for the Cloud SQL instance."
  default     = "us-central1"
}

variable "office_vpn_cidr" {
  type        = string
  description = "The public CIDR IP block of the office VPN allowed to connect directly to the MySQL instance."
  default     = "198.51.100.0/24" # Example documentation range; replace with actual VPN egress CIDR
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Unique suffix to prevent naming collisions if instances are recreated
resource "random_id" "db_suffix" {
  byte_length = 4
}

# Secure random password for the MySQL administrative user
resource "random_password" "mysql_user_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "google_sql_database_instance" "mysql_public_instance" {
  name                = "mysql-vpn-accessible-${random_id.db_suffix.hex}"
  database_version    = "MYSQL_8_0"
  region              = var.region
  deletion_protection = false # Set to true for production workloads

  settings {
    tier              = "db-n1-standard-1"
    availability_type = "ZONAL"
    disk_size         = 20
    disk_type         = "PD_SSD"
    disk_autoresize   = true

    ip_configuration {
      # Allocates a public IPv4 address to the Cloud SQL instance
      ipv4_enabled = true

      # Enforce encryption in transit when accessing over the public internet
      ssl_mode = "ENCRYPTED_ONLY"

      # Restrict public connectivity strictly to the office VPN egress address
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
      start_time         = "03:00"
    }
  }
}

# Default application database
resource "google_sql_database" "default_db" {
  name      = "app_db"
  instance  = google_sql_database_instance.mysql_public_instance.name
  charset   = "utf8mb4"
  collation = "utf8mb4_unicode_ci"
}

# Administrative user for the application
resource "google_sql_user" "app_user" {
  name     = "app_admin"
  instance = google_sql_database_instance.mysql_public_instance.name
  password = random_password.mysql_user_password.result
  host     = "%"
}

output "instance_public_ip" {
  description = "The public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_public_instance.public_ip_address
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_public_instance.connection_name
}

output "database_name" {
  description = "The default database name."
